using System.Collections.Generic;
using System.Text;

namespace Nino.Generator.Generation.Emit;

/// <summary>
/// What every generated file shares: its header, the layout of a file of the <c>NinoGen</c> namespace
/// (<see cref="File"/>), and the aliases the files declare for the names their lines repeat.
/// </summary>
internal static class GeneratedCode
{
    /// <summary>The first lines of every generated file.</summary>
    public const string Header = "// <auto-generated/>\n#nullable disable\n#pragma warning disable\n\n";

    /// <summary>The alias of <c>NinoObject</c> (<c>__NinoObject</c>), a declaration without indent or line break.</summary>
    public const string ObjectAlias = "using __NinoObject = " + TypeNames.Core + "NinoObject;";

    /// <summary>The alias of <c>Writer</c> (<c>__NinoWriter</c>).</summary>
    public const string WriterAlias = "using __NinoWriter = " + TypeNames.Core + "Writer;";

    /// <summary>The alias of <c>Reader</c> (<c>__NinoReader</c>).</summary>
    public const string ReaderAlias = "using __NinoReader = " + TypeNames.Core + "Reader;";

    /// <summary>The alias of <c>NinoDirect</c> (<c>__NinoDirect</c>), which the interceptors call.</summary>
    public const string DirectAlias = "using __NinoDirect = " + TypeNames.Core + "NinoDirect;";

    /// <summary>The alias of <c>InterceptsLocationAttribute</c> (<c>__NinoIntercepts</c>).</summary>
    public const string InterceptsAlias = "using __NinoIntercepts = " + TypeNames.CompilerServices +
                                          "InterceptsLocationAttribute;";

    /// <summary>
    /// A generated file: the <see cref="Header"/>, <paramref name="preamble"/> (assembly attributes, as is), and the
    /// <c>NinoGen</c> namespace holding <paramref name="aliases"/> (declarations, one per line), a blank line and
    /// <paramref name="body"/> (indented one level, as <c>new CodeWriter(indent: 1)</c> writes it).
    /// </summary>
    public static string File(string preamble, IEnumerable<string> aliases, string body)
    {
        var sb = new StringBuilder(Header, body.Length + preamble.Length + 1024);
        sb.Append(preamble);
        sb.Append("namespace " + TypeNames.GenNamespace + "\n{\n");
        foreach (var alias in aliases)
            sb.Append("    ").Append(alias).Append('\n');
        sb.Append('\n');
        sb.Append(body);
        sb.Append("}\n");
        return sb.ToString();
    }

    /// <summary>
    /// The aliases of <c>MethodImplAttribute</c> and <c>MethodImplOptions</c>, one line each (without indent or line
    /// break), that <see cref="Inline"/> and <see cref="NoInline"/> are written with.
    /// </summary>
    public static readonly string[] InlineAliases =
    {
        "using __NinoInline = " + TypeNames.CompilerServices + "MethodImplAttribute;",
        "using __NinoInlineOptions = " + TypeNames.CompilerServices + "MethodImplOptions;",
    };

    /// <summary>The aggressive inlining attribute, through <see cref="InlineAliases"/>.</summary>
    public const string Inline = "[__NinoInline(__NinoInlineOptions.AggressiveInlining)]";

    /// <summary>The no-inlining attribute, through <see cref="InlineAliases"/>.</summary>
    public const string NoInline = "[__NinoInline(__NinoInlineOptions.NoInlining)]";
}
